mod ui;
mod ui_runtime;

const PAGES_TABS: &[&str] = &["⌂ Dashboard", "Agent ● ^1", "QA Team ^2"];
const F_NAME_INPUT: usize = 0;
const F_SUBMIT_BTN: usize = 1;
const F_AGREE: usize = 2;
const F_COLOR: usize = 3;
const F_RESULTS: usize = 4;
const F_FILES: usize = 5;
const F_PAGES: usize = 6;
const FOCUS_COUNT: usize = 7;

/// Where a focusable component was drawn this frame (for mouse clicks).
#[derive(Clone, Copy)]
struct Hit {
    rect: Rect,
    focus: usize,
    modal: bool,
    /// Drawn on the scrolling content: `rect` is in content coordinates, not screen cells.
    scrolls: bool,
}

/// Off-screen surface for the scrolling content; `blit` copies the visible part to the screen.
struct Canvas {
    buf: Buffer,
    cursor: Option<(u16, u16)>,
}

impl Canvas {
    fn new(area: Rect) -> Canvas {
        Canvas {
            buf: Buffer::empty(area),
            cursor: None,
        }
    }

    fn render_widget<W: Widget>(&mut self, widget: W, area: Rect) {
        widget.render(area, &mut self.buf);
    }

    fn render_stateful_widget<W: StatefulWidget>(
        &mut self,
        widget: W,
        area: Rect,
        state: &mut W::State,
    ) {
        widget.render(area, &mut self.buf, state);
    }

    fn set_cursor_position(&mut self, pos: (u16, u16)) {
        self.cursor = Some(pos);
    }

    /// Show the rows `scroll..` of the canvas in `view` on the screen.
    fn blit(&self, frame: &mut Frame, view: Rect, scroll: u16) {
        for dy in 0..view.height {
            for dx in 0..view.width {
                let from = (self.buf.area.x + dx, self.buf.area.y + scroll + dy);
                if let Some(src) = self.buf.cell(from) {
                    if let Some(dst) = frame.buffer_mut().cell_mut((view.x + dx, view.y + dy)) {
                        *dst = src.clone();
                    }
                }
            }
        }
        if let Some((x, y)) = self.cursor {
            if y >= scroll && y - scroll < view.height {
                frame.set_cursor_position((view.x + x, view.y + y - scroll));
            }
        }
    }
}

/// The state of the terminal UI: focus and cursors. Everything the program can see or
/// change lives in the runtime store (`rt`).
struct App {
    rt: Runtime,
    quit: bool,
    hits: Vec<Hit>,
    /// Scroll offset of the content, its maximum, and where the content is shown.
    scroll: u16,
    scroll_max: u16,
    view: Rect,
    /// The select whose list is open, the highlighted option and the list on screen.
    dropdown: Option<usize>,
    dd_cursor: usize,
    dd_state: ListState,
    popup: Option<Rect>,
    focus: Option<usize>,
    tick: usize,
    name_input_cursor: usize,
    results_state: TableState,
    files_state: ListState,
}

impl App {
    fn new(rt: Runtime) -> Self {
        Self {
            rt,
            quit: false,
            hits: Vec::new(),
            scroll: 0,
            scroll_max: 0,
            view: Rect::default(),
            dropdown: None,
            dd_cursor: 0,
            dd_state: ListState::default(),
            popup: None,
            focus: None,
            tick: 0,
            name_input_cursor: 0,
            results_state: TableState::default(),
            files_state: ListState::default(),
        }
    }

    /// The UI is over: the user quit or the program called `stop()`.
    fn finished(&self) -> bool {
        self.quit || self.rt.is_closed()
    }

    fn on_tick(&mut self) {
        self.tick = self.tick.wrapping_add(1);
    }

    /// Scroll the content by `delta` rows.
    fn scroll_by(&mut self, delta: i32) {
        let next = (self.scroll as i32 + delta).clamp(0, self.scroll_max as i32);
        self.scroll = next as u16;
    }

    /// Scroll so that the component with `focus` is fully visible.
    fn reveal(&mut self, focus: usize) {
        let Some(hit) = self.hits.iter().rev().find(|h| h.focus == focus && h.scrolls) else {
            return;
        };
        let (top, bottom) = (hit.rect.y, hit.rect.y + hit.rect.height);
        if top < self.scroll {
            self.scroll = top;
        } else if bottom > self.scroll + self.view.height {
            self.scroll = bottom.saturating_sub(self.view.height).min(top);
        }
        self.scroll = self.scroll.min(self.scroll_max);
    }

    /// Screen position of a focusable component (None when it is scrolled out of view).
    fn field_rect(&self, focus: usize) -> Option<Rect> {
        let hit = self.hits.iter().rev().find(|h| h.focus == focus)?;
        if !hit.scrolls {
            return Some(hit.rect);
        }
        let (top, bottom) = (self.scroll, self.scroll + self.view.height);
        if hit.rect.y < top || hit.rect.y >= bottom {
            return None;
        }
        Some(Rect::new(
            self.view.x + hit.rect.x,
            self.view.y + hit.rect.y - self.scroll,
            hit.rect.width,
            hit.rect.height.min(bottom - hit.rect.y),
        ))
    }

    fn select_key(focus: usize) -> Option<&'static str> {
        match focus {
            F_COLOR => Some("color"),
            _ => None,
        }
    }

    /// Open the list of options of a select.
    fn open_dropdown(&mut self, focus: usize, key: &str) {
        if !self.rt.accepts(key) {
            return;
        }
        let opts = self.rt.get_list(key, "options");
        if opts.is_empty() {
            return;
        }
        let value = self.rt.get_text(key, "value");
        self.dd_cursor = opts.iter().position(|o| *o == value).unwrap_or(0);
        self.dropdown = Some(focus);
    }

    /// Take the option; only a different one is a change.
    fn choose_option(&mut self, key: &str, index: usize) {
        self.dropdown = None;
        let opts = self.rt.get_list(key, "options");
        if let Some(option) = opts.get(index) {
            if *option != self.rt.get_text(key, "value") {
                self.rt.user_set(key, "value", Value::Str(option.clone()), Some("change"));
            }
        }
    }

    /// Keys while the list of options is open.
    fn dropdown_key(&mut self, key: KeyEvent) {
        let Some(focus) = self.dropdown else {
            return;
        };
        let Some(select) = Self::select_key(focus) else {
            self.dropdown = None;
            return;
        };
        let last = self.rt.get_list(select, "options").len().saturating_sub(1);
        match key.code {
            KeyCode::Up => self.dd_cursor = self.dd_cursor.saturating_sub(1),
            KeyCode::Down => self.dd_cursor = (self.dd_cursor + 1).min(last),
            KeyCode::Home => self.dd_cursor = 0,
            KeyCode::End => self.dd_cursor = last,
            KeyCode::Enter | KeyCode::Char(' ') => self.choose_option(select, self.dd_cursor),
            KeyCode::Esc | KeyCode::Tab | KeyCode::BackTab => self.dropdown = None,
            _ => {}
        }
    }

    /// A click while the list is open: inside it chooses, anywhere else closes it.
    fn click_dropdown(&mut self, m: MouseEvent) {
        let Some(focus) = self.dropdown.take() else {
            return;
        };
        let (Some(popup), Some(select)) = (self.popup, Self::select_key(focus)) else {
            return;
        };
        let inside = m.column > popup.x
            && m.column + 1 < popup.x + popup.width
            && m.row > popup.y
            && m.row + 1 < popup.y + popup.height;
        if inside {
            let index = (m.row - popup.y - 1) as usize + self.dd_state.offset();
            self.choose_option(select, index);
        }
    }

    /// Whether the control can take the focus right now.
    fn focusable(&self, id: usize) -> bool {
        let st = self.rt.lock();
        match id {
            F_NAME_INPUT => st.focusable("name_input"),
            F_SUBMIT_BTN => st.focusable("submit_btn"),
            F_AGREE => st.focusable("agree"),
            F_COLOR => st.focusable("color"),
            F_RESULTS => st.focusable("results"),
            F_FILES => st.focusable("files"),
            F_PAGES => st.focusable("pages"),
            _ => true,
        }
    }

    fn focus_next(&mut self) {
        for step in 1..=FOCUS_COUNT {
            let next = match self.focus {
                Some(i) => (i + step) % FOCUS_COUNT,
                None => step - 1,
            };
            if self.focusable(next) {
                self.focus = Some(next);
                self.reveal(next);
                return;
            }
        }
    }

    fn focus_prev(&mut self) {
        for step in 1..=FOCUS_COUNT {
            let prev = match self.focus {
                Some(i) => (i + FOCUS_COUNT - step) % FOCUS_COUNT,
                None => FOCUS_COUNT - step,
            };
            if self.focusable(prev) {
                self.focus = Some(prev);
                self.reveal(prev);
                return;
            }
        }
    }

    fn text_focused(&self) -> bool {
        matches!(self.focus, Some(F_NAME_INPUT))
    }

    /// Every event of the terminal goes through here, also in the tests. Only key presses
    /// count (Windows also reports releases), clicks are hit-tested, anything else just redraws.
    fn on_event(&mut self, event: event::Event) {
        match event {
            event::Event::Key(key) => match key.kind {
                KeyEventKind::Press => self.on_key(key),
                // A held navigation key repeats; a held letter, Space or Enter must not fire again.
                KeyEventKind::Repeat
                    if matches!(
                        key.code,
                        KeyCode::Up
                            | KeyCode::Down
                            | KeyCode::Left
                            | KeyCode::Right
                            | KeyCode::Backspace
                            | KeyCode::Home
                            | KeyCode::End
                    ) =>
                {
                    self.on_key(key)
                }
                _ => {}
            },
            event::Event::Mouse(m) => self.on_mouse(m),
            _ => {}
        }
    }

    /// A left click: focuses and activates the component under the mouse.
    fn on_mouse(&mut self, m: MouseEvent) {
        if self.rt.has_pending() {
            // The error dialog gets the click: it closes.
            if matches!(m.kind, MouseEventKind::Down(MouseButton::Left)) {
                self.rt.dismiss_errors();
            }
            return;
        }
        if self.dropdown.is_some() {
            // The list of options gets the click: it chooses or closes.
            if matches!(m.kind, MouseEventKind::Down(MouseButton::Left)) {
                self.click_dropdown(m);
            }
            return;
        }
        match m.kind {
            MouseEventKind::ScrollDown if !(self.rt.modal_open("confirm")) => {
                self.scroll_by(3);
                return;
            }
            MouseEventKind::ScrollUp if !(self.rt.modal_open("confirm")) => {
                self.scroll_by(-3);
                return;
            }
            _ => {}
        }
        if !matches!(m.kind, MouseEventKind::Down(MouseButton::Left)) {
            return;
        }
        let modal = self.rt.modal_open("confirm");
        // The content is scrolled: its rectangles are in content coordinates.
        let inside = m.column >= self.view.x
            && m.column < self.view.x + self.view.width
            && m.row >= self.view.y
            && m.row < self.view.y + self.view.height;
        let vc = m.column.saturating_sub(self.view.x);
        let vr = m.row.saturating_sub(self.view.y) + self.scroll;
        let hit = self.hits.iter().rev().copied().find(|h| {
            if modal && !h.modal {
                return false;
            }
            let (c, r) = if h.scrolls {
                if !inside {
                    return false;
                }
                (vc, vr)
            } else {
                (m.column, m.row)
            };
            c >= h.rect.x && c < h.rect.x + h.rect.width && r >= h.rect.y && r < h.rect.y + h.rect.height
        });
        let Some(hit) = hit else {
            return;
        };
        if !self.focusable(hit.focus) {
            return;
        }
        self.focus = Some(hit.focus);
        self.reveal(hit.focus);
        let m = if hit.scrolls {
            MouseEvent { column: vc, row: vr, ..m }
        } else {
            m
        };
        match hit.focus {
            F_NAME_INPUT => {
                let col = m.column.saturating_sub(hit.rect.x + 3) as usize;
                self.name_input_cursor = col.min(self.rt.get_text("name_input", "value").chars().count());
            }
            F_SUBMIT_BTN => {
                self.rt.user_emit("submit_btn", "click", Value::None);
            }
            F_AGREE => {
                let on = !self.rt.get_bool("agree", "checked");
                self.rt.user_set("agree", "checked", Value::Bool(on), Some("change"));
            }
            F_COLOR => {
                self.open_dropdown(F_COLOR, "color");
            }
            F_RESULTS => {
                if m.row >= hit.rect.y + 1 + 1 {
                    let row = (m.row - hit.rect.y - 1 - 1) as usize + self.results_state.offset();
                    if row < self.rt.get_rows("results", "rows").len() && self.rt.accepts("results") {
                        self.results_state.select(Some(row));
                    }
                }
            }
            F_FILES => {
                if m.row >= hit.rect.y + 1 {
                    let row = (m.row - hit.rect.y - 1) as usize + self.files_state.offset();
                    let len = self.rt.get_list("files", "items").len();
                    if row < len {
                        self.rt.user_set("files", "selected", Value::Int(row as i64), None);
                        self.rt.user_emit("files", "select", Value::Int(row as i64));
                    }
                }
            }
            F_PAGES => {
                let mut x = hit.rect.x;
                for (i, title) in PAGES_TABS.iter().enumerate() {
                    let width = title.chars().count() as u16 + 2;
                    if m.column >= x && m.column < x + width {
                        if self.rt.get_int("pages", "active_tab") != i as i64 {
                            self.rt.user_set("pages", "active_tab", Value::Int(i as i64), Some("change"));
                        }
                        break;
                    }
                    x += width;
                }
            }
            _ => {}
        }
    }

    /// Every key press of the UI goes through here (also in the tests).
    fn on_key(&mut self, key: KeyEvent) {
        if key.modifiers.contains(KeyModifiers::CONTROL) {
            match key.code {
                KeyCode::Char('c') => {
                    self.quit = true;
                    return;
                }
                KeyCode::Char('l') => {
                    self.rt.toggle_log();
                    return;
                }
                _ => {}
            }
        }
        if self.rt.has_pending() {
            // The error dialog is open: Enter / Esc close it, everything else waits.
            if matches!(key.code, KeyCode::Enter | KeyCode::Esc) {
                self.rt.dismiss_errors();
            }
            return;
        }
        if self.dropdown.is_some() {
            self.dropdown_key(key);
            return;
        }
        let typing = self.text_focused();
        match key.code {
            KeyCode::PageDown => {
                self.scroll_by(self.view.height.max(1) as i32);
                return;
            }
            KeyCode::PageUp => {
                self.scroll_by(-(self.view.height.max(1) as i32));
                return;
            }
            KeyCode::Home if !typing => {
                self.scroll = 0;
                return;
            }
            KeyCode::End if !typing => {
                self.scroll = self.scroll_max;
                return;
            }
            KeyCode::Tab => {
                self.focus_next();
                return;
            }
            KeyCode::BackTab => {
                self.focus_prev();
                return;
            }
            KeyCode::Esc => {
                if typing {
                    self.focus = None;
                } else if self.rt.modal_open("confirm") {
                    self.rt.set("confirm", "open", Value::Bool(false));
                    self.focus = None;
                } else {
                    self.quit = true;
                }
                return;
            }
            KeyCode::Char('q') if !typing => {
                self.quit = true;
                return;
            }
            _ => {}
        }
        match self.focus {
            Some(F_NAME_INPUT) => match key.code {
                KeyCode::Char(c) if !key.modifiers.contains(KeyModifiers::CONTROL) => {
                    if self.rt.accepts("name_input") {
                        let mut v = self.rt.get_text("name_input", "value");
                        let at_char = self.name_input_cursor.min(v.chars().count());
                        let at = byte_index(&v, at_char);
                        v.insert(at, c);
                        self.name_input_cursor = at_char + 1;
                        self.rt.user_set("name_input", "value", Value::Str(v), Some("change"));
                    }
                }
                KeyCode::Backspace => {
                    if self.rt.accepts("name_input") {
                        let mut v = self.rt.get_text("name_input", "value");
                        let at_char = self.name_input_cursor.min(v.chars().count());
                        if at_char > 0 {
                            let at = byte_index(&v, at_char - 1);
                            v.remove(at);
                            self.name_input_cursor = at_char - 1;
                            self.rt.user_set("name_input", "value", Value::Str(v), Some("change"));
                        }
                    }
                }
                KeyCode::Left => {
                    self.name_input_cursor = self.name_input_cursor.saturating_sub(1);
                }
                KeyCode::Right => {
                    let n = self.rt.get_text("name_input", "value").chars().count();
                    self.name_input_cursor = (self.name_input_cursor + 1).min(n);
                }
                KeyCode::Home => {
                    self.name_input_cursor = 0;
                }
                KeyCode::End => {
                    self.name_input_cursor = self.rt.get_text("name_input", "value").chars().count();
                }
                KeyCode::Enter => {
                    let v = self.rt.get_text("name_input", "value");
                    self.rt.user_emit("name_input", "submit", Value::Str(v));
                }
                _ => {}
            },
            Some(F_SUBMIT_BTN) => match key.code {
                KeyCode::Enter | KeyCode::Char(' ') => {
                    self.rt.user_emit("submit_btn", "click", Value::None);
                }
                _ => {}
            },
            Some(F_AGREE) => match key.code {
                KeyCode::Char(' ') | KeyCode::Enter => {
                    let on = !self.rt.get_bool("agree", "checked");
                    self.rt.user_set("agree", "checked", Value::Bool(on), Some("change"));
                }
                _ => {}
            },
            Some(F_COLOR) => match key.code {
                KeyCode::Enter | KeyCode::Char(' ') | KeyCode::Up | KeyCode::Down => {
                    self.open_dropdown(F_COLOR, "color");
                }
                _ => {}
            },
            Some(F_RESULTS) => match key.code {
                KeyCode::Up | KeyCode::Down => {
                    if self.rt.accepts("results") {
                        let cur = self.results_state.selected().unwrap_or(0);
                        let last = self.rt.get_rows("results", "rows").len().saturating_sub(1);
                        let next = if key.code == KeyCode::Up {
                            cur.saturating_sub(1)
                        } else {
                            (cur + 1).min(last)
                        };
                        self.results_state.select(Some(next));
                    }
                }
                _ => {}
            },
            Some(F_FILES) => match key.code {
                KeyCode::Up | KeyCode::Down => {
                    let cur = self.rt.get_int("files", "selected");
                    let last = (self.rt.get_list("files", "items").len() as i64 - 1).max(0);
                    let step = if key.code == KeyCode::Up { -1 } else { 1 };
                    self.rt.user_set("files", "selected", Value::Int((cur + step).clamp(0, last)), None);
                }
                KeyCode::Enter => {
                    let cur = self.rt.get_int("files", "selected");
                    self.rt.user_emit("files", "select", Value::Int(cur));
                }
                _ => {}
            },
            Some(F_PAGES) => match key.code {
                KeyCode::Left | KeyCode::Right => {
                    let cur = self.rt.get_int("pages", "active_tab");
                    let step = if key.code == KeyCode::Left { -1 } else { 1 };
                    let last = (PAGES_TABS.len() as i64 - 1).max(0);
                    let next = (cur + step).clamp(0, last);
                    if next != cur {
                        self.rt.user_set("pages", "active_tab", Value::Int(next), Some("change"));
                    }
                }
                _ => {}
            },
            _ => {}
        }
    }
}

/// Byte offset of the `chars`-th character.
fn byte_index(s: &str, chars: usize) -> usize {
    s.char_indices().nth(chars).map(|(i, _)| i).unwrap_or(s.len())
}

