fn handle_change(_event: &Event) { /* TODO */ }
fn handle_click(_event: &Event) { /* TODO */ }
fn handle_select(_event: &Event) { /* TODO */ }

fn register_handlers(ui: &Ui) {
    ui.name_input.on_change(handle_change);
    ui.submit_btn.on_click(handle_click);
    ui.agree.on_change(handle_change);
    ui.color.on_change(handle_change);
    ui.files.on_select(handle_select);
}

fn main() -> Result<(), UiError> {
    let ui = Ui::new();
    register_handlers(&ui);
    // The UI runs on this thread, `program` on its own thread next to it.
    ui.run(program)
}

/// Your program goes here. It runs next to the UI, which keeps running when this returns.
/// Components with a code name are fields of `ui`, for example:
///     ui.status.set_text("Ready");
///     ui.log().info("started");
fn program(ui: Ui) {
    let _ = ui;
}

fn read_event(timeout: Duration) -> io::Result<Option<event::Event>> {
    if event::poll(timeout)? {
        return Ok(Some(event::read()?));
    }
    Ok(None)
}

/// The UI loop: draw, then wait for an event. `input` and `on_frame` let tests run it headless.
fn run_loop<B, I, D>(
    terminal: &mut Terminal<B>,
    app: &mut App,
    mut input: I,
    mut on_frame: D,
) -> io::Result<()>
where
    B: Backend,
    I: FnMut(Duration) -> io::Result<Option<event::Event>>,
    D: FnMut(&Buffer),
{
    while !app.finished() {
        let frame = terminal.draw(|f| ui(f, app))?;
        on_frame(frame.buffer);
        match input(Duration::from_millis(30))? {
            Some(event) => app.on_event(event),
            None => app.on_tick(),
        }
    }
    Ok(())
}

fn ui(frame: &mut Frame, app: &mut App) {
    let st = app.rt.lock();
    app.hits.clear();
    app.popup = None;
    let full = frame.area();
    let area = if st.log_visible() {
        let parts = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Fill(1),
                Constraint::Length((full.height / 3).max(3).min(full.height)),
            ])
            .split(full);
        render_log(frame, &st, parts[1]);
        parts[0]
    } else {
        full
    };
    let demo_area = area;
    let demo_block = Block::default().borders(Borders::ALL).border_type(BorderType::Plain).border_style(Style::default().fg(Color::Rgb(248, 248, 242))).padding(Padding::new(1, 1, 1, 1)).style(Style::default().fg(Color::Rgb(248, 248, 242)));
    let demo_inner = demo_block.inner(demo_area);
    frame.render_widget(demo_block, demo_area);
    let demo_show = [st.shown("status"), st.shown("name_input"), st.shown("submit_btn"), st.shown("agree"), st.shown("color"), st.shown("progress"), st.shown("results"), st.shown("files"), st.shown("pages"), st.shown("panel")];
    let demo_slot = slots(&demo_show);
    let demo_cs: Vec<Constraint> = [Constraint::Length(1), Constraint::Length(3), Constraint::Length(3), Constraint::Length(1), Constraint::Length(3), Constraint::Length(3), Constraint::Length(5), Constraint::Length(5), Constraint::Length(2), Constraint::Length(5)]
        .iter()
        .zip(demo_show.iter())
        .filter(|(_, s)| **s)
        .map(|(c, _)| *c)
        .collect();
    let demo_need: u16 = demo_cs.iter().map(|c| match c { Constraint::Length(n) => *n, _ => 0 }).sum::<u16>() + 0 * (demo_cs.len().saturating_sub(1) as u16);
    let demo_virt = Rect::new(0, 0, demo_inner.width, demo_need.max(demo_inner.height));
    app.view = demo_inner;
    app.scroll_max = demo_need.saturating_sub(demo_inner.height);
    app.scroll = app.scroll.min(app.scroll_max);
    let mut cv = Canvas::new(demo_virt);
    let demo_cells = Layout::default()
        .direction(Direction::Vertical)
        .flex(Flex::Start)
        .constraints(demo_cs)
        .split(demo_virt);
    if st.shown("status") {
        let status_area = demo_cells[demo_slot[0]];
        cv.render_widget(
            Paragraph::new(st.text("status", "text"))
                .style(Style::default().fg(Color::Rgb(248, 248, 242))),
            status_area,
        );
    }
    if st.shown("name_input") {
        let name_input_area = aligned(demo_cells[demo_slot[1]], 20, u16::MAX, 0, 0);
        app.hits.push(Hit { rect: name_input_area, focus: F_NAME_INPUT, modal: false, scrolls: true });
        let name_input_text = if st.text("name_input", "value").is_empty() {
            Span::styled(st.text("name_input", "placeholder"), Style::default().fg(Color::Rgb(128, 128, 128)))
        } else {
            Span::raw(st.text("name_input", "value"))
        };
        let name_input_block = Block::default().borders(Borders::ALL).border_type(BorderType::Plain).border_style(focus_border(Style::default().fg(Color::Rgb(248, 248, 242)), app.focus == Some(F_NAME_INPUT))).padding(Padding::horizontal(2));
        let name_input_inner = name_input_block.inner(name_input_area);
        cv.render_widget(
            Paragraph::new(name_input_text)
                .style(dim_if(Style::default().fg(Color::Rgb(248, 248, 242)), st.muted("name_input")))
                .block(name_input_block),
            name_input_area,
        );
        if app.focus == Some(F_NAME_INPUT) {
            cv.set_cursor_position((
                name_input_inner.x + (app.name_input_cursor.min(st.text("name_input", "value").chars().count()) as u16).min(name_input_inner.width.saturating_sub(1)),
                name_input_inner.y,
            ));
        }
    }
    if st.shown("submit_btn") {
        let submit_btn_area = aligned(demo_cells[demo_slot[2]], button_width(&format!("{}{}{}", "", st.text("submit_btn", "label"), ""), 2), u16::MAX, 0, 0);
        app.hits.push(Hit { rect: submit_btn_area, focus: F_SUBMIT_BTN, modal: false, scrolls: true });
        cv.render_widget(
            Paragraph::new(st.text("submit_btn", "label"))
                .style(dim_if(Style::default().fg(Color::Rgb(248, 248, 242)).add_modifier(Modifier::BOLD), st.muted("submit_btn")))
                .alignment(Alignment::Center)
                .block(Block::default().borders(Borders::ALL).border_type(BorderType::Rounded).border_style(focus_border(Style::default().fg(Color::Rgb(248, 248, 242)), app.focus == Some(F_SUBMIT_BTN)))),
            submit_btn_area,
        );
    }
    if st.shown("agree") {
        let agree_area = demo_cells[demo_slot[3]];
        app.hits.push(Hit { rect: agree_area, focus: F_AGREE, modal: false, scrolls: true });
        cv.render_widget(
            Paragraph::new(format!("[{}] {}", if st.boolean("agree", "checked") { "✓" } else { " " }, st.text("agree", "label")))
                .style(focus_style(dim_if(Style::default().fg(Color::Rgb(248, 248, 242)), st.muted("agree")), app.focus == Some(F_AGREE))),
            agree_area,
        );
    }
    if st.shown("color") {
        let color_area = demo_cells[demo_slot[4]];
        app.hits.push(Hit { rect: color_area, focus: F_COLOR, modal: false, scrolls: true });
        let color_value = st.text("color", "value");
        let color_room = (color_area.width as usize).saturating_sub(2);
        let color_line = format!("  {}{}▼  ", color_value, " ".repeat(color_room.saturating_sub(color_value.chars().count() + 5)));
        cv.render_widget(
            Paragraph::new(color_line)
                .style(dim_if(Style::default().fg(Color::Rgb(248, 248, 242)), st.muted("color")))
                .block(Block::default().borders(Borders::ALL).border_type(BorderType::Plain).border_style(focus_border(Style::default().fg(Color::Rgb(248, 248, 242)), app.focus == Some(F_COLOR)))),
            color_area,
        );
    }
    if st.shown("progress") {
        let progress_area = aligned(demo_cells[demo_slot[5]], 20, u16::MAX, 0, 0);
        let progress_ratio = {
            let max = st.float("progress", "max");
            if max > 0.0 { (st.float("progress", "value") / max).clamp(0.0, 1.0) } else { 0.0 }
        };
        let progress_room = (progress_area.width as usize).saturating_sub(7).max(1);
        let progress_filled = ((progress_ratio * progress_room as f64).round() as usize).min(progress_room);
        let progress_pct = format!("{}%", (progress_ratio * 100.0).round() as u32);
        cv.render_widget(
            Paragraph::new(Line::from(vec![
                Span::styled("█".repeat(progress_filled), Style::default().fg(Color::Rgb(248, 248, 242))),
                Span::styled("░".repeat(progress_room - progress_filled), Style::default().fg(Color::DarkGray)),
                Span::raw(format!("{:>5}", progress_pct)),
                ]))
                .block(Block::default().borders(Borders::ALL).border_type(BorderType::Plain).border_style(Style::default().fg(Color::Rgb(248, 248, 242)))),
            progress_area,
        );
    }
    if st.shown("results") {
        let results_area = aligned(demo_cells[demo_slot[6]], table_width(st.list("results", "columns"), st.rows("results", "rows"), 2), u16::MAX, 0, 0);
        app.hits.push(Hit { rect: results_area, focus: F_RESULTS, modal: false, scrolls: true });
        let results_cols = st.list("results", "columns");
        let results_rows = st.rows("results", "rows");
        let results_n = results_rows.iter().map(|r| r.len()).chain([results_cols.len()]).max().unwrap_or(1).max(1);
        let results_w: Vec<usize> = (0..results_n)
            .map(|c| {
                results_rows
                    .iter()
                    .map(|r| r.get(c).map_or(0, |s| s.chars().count()))
                    .chain(results_cols.get(c).map(|s| s.chars().count()))
                    .max()
                    .unwrap_or(0)
                    .max(3)
            })
            .collect();
        app.results_state.select(if results_rows.is_empty() {
            None
        } else {
            Some(app.results_state.selected().unwrap_or(0).min(results_rows.len() - 1))
        });
        let results_head = Row::new((0..results_n).map(|c| Cell::from(results_cols.get(c).cloned().unwrap_or_default())))
            .style(Style::default().add_modifier(Modifier::BOLD));
        cv.render_stateful_widget(
            Table::new(results_rows.iter().map(|r| Row::new(r.clone())), results_w.iter().map(|w| Constraint::Length(*w as u16)).collect::<Vec<_>>())
                .style(dim_if(Style::default().fg(Color::Rgb(248, 248, 242)), st.muted("results")))
                .column_spacing(2)
                .header(results_head)
                .row_highlight_style(focus_style(Style::default().add_modifier(Modifier::BOLD), app.focus == Some(F_RESULTS)))
                .block(Block::default().borders(Borders::ALL).border_type(BorderType::Plain).border_style(focus_border(Style::default().fg(Color::Rgb(248, 248, 242)), app.focus == Some(F_RESULTS))).padding(Padding::horizontal(1))),
            results_area,
            &mut app.results_state,
        );
    }
    if st.shown("files") {
        let files_area = demo_cells[demo_slot[7]];
        app.hits.push(Hit { rect: files_area, focus: F_FILES, modal: false, scrolls: true });
        let files_items = st.list("files", "items");
        app.files_state.select(if files_items.is_empty() {
            None
        } else {
            Some((st.int("files", "selected").max(0) as usize).min(files_items.len() - 1))
        });
        cv.render_stateful_widget(
            List::new(files_items.to_vec())
                .style(dim_if(Style::default().fg(Color::Rgb(248, 248, 242)), st.muted("files")))
                .highlight_style(focus_style(Style::default().add_modifier(Modifier::BOLD), app.focus == Some(F_FILES)))
                .block(Block::default().borders(Borders::ALL).border_type(BorderType::Plain).border_style(focus_border(Style::default().fg(Color::Rgb(248, 248, 242)), app.focus == Some(F_FILES)))),
            files_area,
            &mut app.files_state,
        );
    }
    if st.shown("pages") {
        let pages_area = demo_cells[demo_slot[8]];
        app.hits.push(Hit { rect: pages_area, focus: F_PAGES, modal: false, scrolls: true });
        let pages_bar = Rect { height: pages_area.height.min(1), ..pages_area };
        cv.render_widget(
            Tabs::new(PAGES_TABS.to_vec())
                .style(dim_if(Style::default().fg(Color::Rgb(248, 248, 242)), st.muted("pages")))
                .select(st.int("pages", "active_tab").max(0) as usize)
                .padding(" ", " ")
                .divider("")
                .highlight_style(focus_style(Style::default().add_modifier(Modifier::BOLD), app.focus == Some(F_PAGES))),
            pages_bar,
        );
        if pages_area.height > 1 {
            let pages_active = (st.int("pages", "active_tab").max(0) as usize).min(PAGES_TABS.len().saturating_sub(1));
            let pages_before: usize = PAGES_TABS.iter().take(pages_active).map(|t| t.chars().count() + 2).sum();
            let pages_span = PAGES_TABS.get(pages_active).map_or(0, |t| t.chars().count() + 2);
            let pages_rest = (pages_area.width as usize).saturating_sub(pages_before + pages_span);
            let pages_rule = format!(
                "{}{}{}{}",
                "━".repeat(pages_before.min(pages_area.width as usize)),
                if pages_span > 0 { "╸" } else { "" },
                "━".repeat(pages_span.saturating_sub(2)),
                if pages_span > 1 { "╺" } else { "" },
            );
            cv.render_widget(Paragraph::new(format!("{}{}", pages_rule, "━".repeat(pages_rest))), Rect { y: pages_area.y + 1, height: 1, ..pages_area });
        }
    }
    if st.shown("panel") {
        let panel_area = aligned(demo_cells[demo_slot[9]], 20, u16::MAX, 0, 0);
        let panel_block = Block::default().borders(Borders::ALL).border_type(BorderType::Plain).border_style(Style::default().fg(Color::Rgb(248, 248, 242))).padding(Padding::new(1, 1, 1, 1)).style(Style::default().fg(Color::Rgb(248, 248, 242)));
        let panel_inner = panel_block.inner(panel_area);
        cv.render_widget(panel_block, panel_area);
        let panel_show = [st.shown("inner")];
        let panel_slot = slots(&panel_show);
        let panel_cs: Vec<Constraint> = [Constraint::Length(1)]
            .iter()
            .zip(panel_show.iter())
            .filter(|(_, s)| **s)
            .map(|(c, _)| *c)
            .collect();
        let panel_virt = Rect { height: panel_inner.height.max(1), ..panel_inner };
        let panel_cells = Layout::default()
            .direction(Direction::Vertical)
            .flex(Flex::Start)
            .spacing(1)
            .constraints(panel_cs)
            .split(panel_virt);
        if st.shown("inner") {
            let inner_area = panel_cells[panel_slot[0]].intersection(panel_inner);
            cv.render_widget(
                Paragraph::new(st.text("inner", "text"))
                    .style(Style::default().fg(Color::Rgb(248, 248, 242))),
                inner_area,
            );
        }
    }
    cv.blit(frame, demo_inner, app.scroll);
    if app.scroll_max > 0 {
        let mut demo_bar = ScrollbarState::new(app.scroll_max as usize + 1)
            .position(app.scroll as usize)
            .viewport_content_length(demo_inner.height as usize);
        frame.render_stateful_widget(
            Scrollbar::new(ScrollbarOrientation::VerticalRight)
                .begin_symbol(None)
                .end_symbol(None)
                .track_symbol(Some("│"))
                .thumb_symbol("█"),
            Rect { x: demo_area.x, y: demo_inner.y, width: demo_area.width, height: demo_inner.height },
            &mut demo_bar,
        );
    }
    if st.modal_open("confirm") {
        let confirm_area = centered(area, 40, 12);
        frame.render_widget(Clear, confirm_area);
        let confirm_block = Block::default().borders(Borders::ALL).border_type(BorderType::Double).border_style(Style::default().fg(Color::Rgb(248, 248, 242))).padding(Padding::new(2, 2, 2, 2)).title(st.text("confirm", "title")).style(Style::default().fg(Color::Rgb(248, 248, 242)).bg(Color::Rgb(33, 34, 44)));
        let confirm_inner = confirm_block.inner(confirm_area);
        frame.render_widget(confirm_block, confirm_area);
        let confirm_virt = Rect { height: confirm_inner.height.max(1), ..confirm_inner };
        let confirm_cells = Layout::default()
            .direction(Direction::Vertical)
            .flex(Flex::Start)
            .constraints([Constraint::Length(1)])
            .split(confirm_virt);
        let text_area = aligned(confirm_cells[0].intersection(confirm_inner), 7, u16::MAX, 0, 0);
        frame.render_widget(
            Paragraph::new(st.text("_text", "text"))
                .style(Style::default().fg(Color::Rgb(248, 248, 242))),
            text_area,
        );
    }
    if app.dropdown == Some(F_COLOR) {
        let opts = st.list("color", "options");
        match app.field_rect(F_COLOR).filter(|_| !opts.is_empty() && st.state("color") == State::Active) {
            Some(field) => {
                let popup = dropdown_area(field, opts.len(), opts.iter().map(|o| o.chars().count()).max().unwrap_or(0), full);
                frame.render_widget(Clear, popup);
                app.dd_state.select(Some(app.dd_cursor.min(opts.len() - 1)));
                frame.render_stateful_widget(
                    List::new(opts.to_vec())
                        .block(Block::default().borders(Borders::ALL))
                        .style(dim_if(Style::default().fg(Color::Rgb(248, 248, 242)), st.muted("color")))
                        .highlight_style(Style::default().add_modifier(Modifier::REVERSED))
                        .highlight_symbol("> "),
                    popup,
                    &mut app.dd_state,
                );
                app.popup = Some(popup);
            }
            None => app.dropdown = None,
        }
    }
    render_errors(frame, &st, full);
}

fn render_log(frame: &mut Frame, st: &Store, area: Rect) {
    let rows = area.height.saturating_sub(2) as usize;
    let log = st.log();
    let start = log.len().saturating_sub(rows);
    let lines: Vec<Line> = log[start..]
        .iter()
        .map(|e| Line::from(format!("{:>7} {}", e.level.name(), e.message.replace('\n', " "))))
        .collect();
    frame.render_widget(
        Paragraph::new(lines).block(
            Block::default()
                .borders(Borders::ALL)
                .title("Log (Ctrl+L closes)"),
        ),
        area,
    );
}

fn render_errors(frame: &mut Frame, st: &Store, full: Rect) {
    let pending = st.pending();
    if pending.is_empty() {
        return;
    }
    let mut lines: Vec<Line> = Vec::new();
    for e in pending {
        lines.push(Line::from(e.message.clone()));
        if !e.details.is_empty() {
            lines.push(Line::from(format!("  {}", e.details)));
        }
    }
    lines.push(Line::from(""));
    lines.push(Line::from("Enter / Esc: close"));
    let width = full.width.saturating_sub(4).clamp(20, 64);
    let height = (lines.len() as u16 + 2).min(full.height);
    let area = centered(full, width, height);
    frame.render_widget(Clear, area);
    frame.render_widget(
        Paragraph::new(lines).wrap(Wrap { trim: false }).block(
            Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Double)
                .border_style(Style::default().fg(Color::Rgb(255, 85, 85)))
                .title("Error"),
        ),
        area,
    );
}

/// Highlight for the widget that has the keyboard focus.
fn focus_style(style: Style, focused: bool) -> Style {
    if focused {
        style.add_modifier(Modifier::REVERSED)
    } else {
        style
    }
}

fn focus_border(style: Style, focused: bool) -> Style {
    if focused {
        style.fg(Color::Rgb(255, 215, 0))
    } else {
        style
    }
}

/// Muted components are drawn dimmed.
fn dim_if(style: Style, dim: bool) -> Style {
    if dim {
        style.add_modifier(Modifier::DIM)
    } else {
        style
    }
}

/// Position of each child among the children that are shown.
fn slots(show: &[bool]) -> Vec<usize> {
    let mut next = 0;
    show.iter()
        .map(|s| {
            let slot = next;
            if *s {
                next += 1;
            }
            slot
        })
        .collect()
}

/// Width of a button: its label with two cells of padding on each side, at least 16 when bordered.
fn button_width(label: &str, border: u16) -> u16 {
    let w = label.chars().count() as u16;
    if border > 0 {
        (w + 4 + border).max(16)
    } else {
        w
    }
}

/// Width of a table: the widest cell of each column, two cells between columns and one of padding on each side.
fn table_width(cols: &[String], rows: &[Vec<String>], border: u16) -> u16 {
    let n = rows.iter().map(|r| r.len()).chain([cols.len()]).max().unwrap_or(1).max(1);
    let cells: usize = (0..n)
        .map(|c| {
            rows.iter()
                .map(|r| r.get(c).map_or(0, |s| s.chars().count()))
                .chain(cols.get(c).map(|s| s.chars().count()))
                .max()
                .unwrap_or(0)
                .max(3)
        })
        .sum();
    (cells + 2 * (n - 1) + 2) as u16 + border
}

/// The list of a select: under the field, or above it when there is no room below.
fn dropdown_area(field: Rect, count: usize, widest: usize, bounds: Rect) -> Rect {
    let width = (widest as u16 + 4).max(field.width).min(bounds.width);
    let want = count as u16 + 2;
    let below = bounds.bottom().saturating_sub(field.bottom());
    let above = field.y.saturating_sub(bounds.y);
    let x = field.x.min(bounds.right().saturating_sub(width));
    if below >= want || below >= above {
        Rect::new(x, field.bottom(), width, want.min(below))
    } else {
        let height = want.min(above);
        Rect::new(x, field.y - height, width, height)
    }
}

/// Place a w x h rectangle inside `area`; ax/ay: 0 = start, 1 = center, 2 = end.
fn aligned(area: Rect, w: u16, h: u16, ax: u8, ay: u8) -> Rect {
    let w = w.min(area.width);
    let h = h.min(area.height);
    let x = match ax {
        1 => area.x + (area.width - w) / 2,
        2 => area.x + (area.width - w),
        _ => area.x,
    };
    let y = match ay {
        1 => area.y + (area.height - h) / 2,
        2 => area.y + (area.height - h),
        _ => area.y,
    };
    Rect::new(x, y, w, h)
}

fn centered(area: Rect, w: u16, h: u16) -> Rect {
    aligned(area, w, h, 1, 1)
}
